3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { realUser } from "./auth";
7	import { requireArea } from "./rbac";
8	import { validateImageBytes } from "./chat-attachment";
9	import { checkRateLimit } from "./rate-limit";
10	import { markTyping, readTyping } from "./chat-typing";
11	
12	/**
13	 * Staff-side live-chat actions. Every export gates on `requireArea("support")`
14	 * so only support staff / admins can read or write conversations. This file is
15	 * a "use server" module, so it may export **async functions only**.
16	 */
17	
18	/** Shape returned to the admin inbox client component. */
19	type InboxAttachment = { id: string; mime: string; sizeBytes: number } | null;
20	type InboxMessage = {
21	  id: string;
22	  sender: string;
23	  body: string;
24	  createdAt: string;
25	  attachment: InboxAttachment;
26	};
27	type InboxConversation = {
28	  id: string;
29	  visitorId: string;
30	  userId: string | null;
31	  name: string | null;
32	  email: string | null;
33	  status: string;
34	  assignedToId: string | null;
35	  /** Display name of the staff member handling it, resolved from assignedToId. */
36	  assignedToName: string | null;
37	  unreadForAgent: boolean;
38	  lastMessageAt: string;
39	  createdAt: string;
40	  /** True while the visitor is composing (transient, self-expiring). */
41	  visitorTyping: boolean;
42	  messages: InboxMessage[];
43	};
44	
45	/**
46	 * Resolve staff user ids to display names in one query. Not a "use server"
47	 * export (it takes non-serializable args and isn't called from the client);
48	 * used internally to attach `assignedToName` to inbox payloads so the admin
49	 * thread view can label each human reply with the agent handling it.
50	 */
51	async function resolveStaffNames(
52	  ids: (string | null)[]
53	): Promise<Map<string, string>> {
54	  const unique = Array.from(new Set(ids.filter((v): v is string => !!v)));
55	  if (unique.length === 0) return new Map();
56	  const users = await db.user.findMany({
57	    where: { id: { in: unique } },
58	    select: { id: true, name: true },
59	  });
60	  return new Map(users.map((u) => [u.id, u.name]));
61	}
62	
63	/** List conversations for the inbox, unread + newest first. Polled by the client. */
64	export async function listConversations(): Promise<InboxConversation[]> {
65	  await requireArea("support");
66	  const rows = await db.chatConversation.findMany({
67	    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
68	    take: 200,
69	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
70	  });
71	  const staffNames = await resolveStaffNames(rows.map((c) => c.assignedToId));
72	  return rows.map((c) => ({
73	    id: c.id,
74	    visitorId: c.visitorId,
75	    userId: c.userId,
76	    name: c.name,
77	    email: c.email,
78	    status: c.status,
79	    assignedToId: c.assignedToId,
80	    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
81	    unreadForAgent: c.unreadForAgent,
82	    lastMessageAt: c.lastMessageAt.toISOString(),
83	    createdAt: c.createdAt.toISOString(),
84	    visitorTyping: readTyping(c.id).visitor,
85	    messages: c.messages.map((m) => ({
86	      id: m.id,
87	      sender: m.sender,
88	      body: m.body,
89	      createdAt: m.createdAt.toISOString(),
90	      attachment: m.attachment
91	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
92	        : null,
93	    })),
94	  }));
95	}
96	
97	/** Fetch a single conversation's messages (used when opening / polling a thread). */
98	export async function getConversation(id: string): Promise<InboxConversation | null> {
99	  await requireArea("support");
100	  if (typeof id !== "string" || !id) return null;
101	  const c = await db.chatConversation.findUnique({
102	    where: { id },
103	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
104	  });
105	  if (!c) return null;
106	  const staffNames = await resolveStaffNames([c.assignedToId]);
107	  return {
108	    id: c.id,
109	    visitorId: c.visitorId,
110	    userId: c.userId,
111	    name: c.name,
112	    email: c.email,
113	    status: c.status,
114	    assignedToId: c.assignedToId,
115	    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
116	    unreadForAgent: c.unreadForAgent,
117	    lastMessageAt: c.lastMessageAt.toISOString(),
118	    createdAt: c.createdAt.toISOString(),
119	    visitorTyping: readTyping(c.id).visitor,
120	    messages: c.messages.map((m) => ({
121	      id: m.id,
122	      sender: m.sender,
123	      body: m.body,
124	      createdAt: m.createdAt.toISOString(),
125	      attachment: m.attachment
126	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
127	        : null,
128	    })),
129	  };
130	}
131	
132	/**
133	 * Staff reply: append an "agent" message, flag the thread unread for the user,
134	 * clear the agent-unread flag, and assign it to the replying staff member.
135	 */
136	export async function replyToConversation(
137	  id: string,
138	  body: string
139	): Promise<{ error?: string; ok?: boolean }> {
140	  const staff = await requireArea("support");
141	
142	  const parsed = z
143	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
144	    .safeParse({ id, body });
145	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
146	
147	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
148	  if (!convo) return { error: "Conversation not found." };
149	
150	  await db.$transaction([
151	    db.chatMessage.create({
152	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
153	    }),
154	    db.chatConversation.update({
155	      where: { id: parsed.data.id },
156	      data: {
157	        status: "OPEN",
158	        unreadForUser: true,
159	        unreadForAgent: false,
160	        assignedToId: staff.id,
161	        lastMessageAt: new Date(),
162	      },
163	    }),
164	  ]);
165	
166	  // If the visitor is a signed-in customer, drop them a notification.
167	  if (convo.userId) {
168	    await db.notification
169	      .create({
170	        data: {
171	          userId: convo.userId,
172	          title: "New reply in your live chat",
173	          href: "/dashboard",
174	        },
175	      })
176	      .catch(() => {});
177	  }
178	
179	  revalidatePath("/admin/chat");
180	  return { ok: true };
181	}
182	
183	/**
184	 * Staff reply carrying an image attachment. Same authorization and side effects
185	 * as `replyToConversation` (requireArea("support"), notify, assign, unread) but
186	 * the message body may be empty and it stores a signature-verified image in
187	 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
188	 * rejection) run in `validateImageBytes` — the client cannot bypass them.
189	 */
190	export async function replyWithAttachment(
191	  formData: FormData
192	): Promise<{ error?: string; ok?: boolean }> {
193	  const staff = await requireArea("support");
194	
195	  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
196	  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
197	  if (!rl.ok) return { error: "Too many uploads. Please slow down." };
198	
199	  const id = formData.get("conversationId");
200	  const rawBody = formData.get("body");
201	  const file = formData.get("file");
202	
203	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
204	  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
205	  if (!(file instanceof File)) return { error: "No image provided." };
206	  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };
207	
208	  const convo = await db.chatConversation.findUnique({ where: { id } });
209	  if (!convo) return { error: "Conversation not found." };
210	
211	  const bytes = Buffer.from(await file.arrayBuffer());
212	  const check = validateImageBytes(bytes, file.type);
213	  if (!check.ok) return { error: check.error };
214	
215	  await db.$transaction(async (tx) => {
216	    const msg = await tx.chatMessage.create({
217	      data: { conversationId: id, sender: "agent", body },
218	    });
219	    await tx.chatAttachment.create({
220	      data: {
221	        messageId: msg.id,
222	        mime: check.mime,
223	        sizeBytes: check.bytes.length,
224	        data: new Uint8Array(check.bytes),
225	      },
226	    });
227	    await tx.chatConversation.update({
228	      where: { id },
229	      data: {
230	        status: "OPEN",
231	        unreadForUser: true,
232	        unreadForAgent: false,
233	        assignedToId: staff.id,
234	        lastMessageAt: new Date(),
235	      },
236	    });
237	  });
238	
239	  if (convo.userId) {
240	    await db.notification
241	      .create({
242	        data: {
243	          userId: convo.userId,
244	          title: "New reply in your live chat",
245	          href: "/dashboard",
246	        },
247	      })
248	      .catch(() => {});
249	  }
250	
251	  revalidatePath("/admin/chat");
252	  return { ok: true };
253	}
254	
255	/** Close a conversation (staff). */
256	export async function closeConversation(
257	  id: string
258	): Promise<{ error?: string; ok?: boolean }> {
259	  await requireArea("support");
260	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
261	  const convo = await db.chatConversation.findUnique({ where: { id } });
262	  if (!convo) return { error: "Conversation not found." };
263	  await db.chatConversation.update({
264	    where: { id },
265	    data: { status: "CLOSED", unreadForAgent: false },
266	  });
267	  revalidatePath("/admin/chat");
268	  return { ok: true };
269	}
270	
271	/**
272	 * Bulk-close every currently OPEN conversation (staff "Close all" action).
273	 * Returns how many were closed so the client can surface a confirmation.
274	 */
275	export async function closeAllConversations(): Promise<{ closed: number }> {
276	  await requireArea("support");
277	  const res = await db.chatConversation.updateMany({
278	    where: { status: "OPEN" },
279	    data: { status: "CLOSED", unreadForAgent: false },
280	  });
281	  revalidatePath("/admin/chat");
282	  return { closed: res.count };
283	}
284	
285	/** Assign a conversation to the acting staff member and mark it read for agents. */
286	export async function assignConversation(
287	  id: string
288	): Promise<{ error?: string; ok?: boolean }> {
289	  const staff = await requireArea("support");
290	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
291	  const convo = await db.chatConversation.findUnique({ where: { id } });
292	  if (!convo) return { error: "Conversation not found." };
293	  await db.chatConversation.update({
294	    where: { id },
295	    data: { assignedToId: staff.id, unreadForAgent: false },
296	  });
297	  revalidatePath("/admin/chat");
298	  return { ok: true };
299	}
300	
301	/**
302	 * Record that the acting agent is composing a reply, so the visitor's widget can
303	 * show a "typing…" indicator. Transient and self-expiring (lib/chat-typing.ts):
304	 * no DB write, no revalidation — the admin inbox calls this at most once every
305	 * couple of seconds while the reply box has focus and content.
306	 */
307	export async function signalAgentTyping(conversationId: string): Promise<void> {
308	  await requireArea("support");
309	  if (typeof conversationId !== "string" || !conversationId) return;
310	  markTyping(conversationId, "agent");
311	}
