1	/**
2	 * Transient "what the bot is doing right now" signal for the live chat, kept in
3	 * memory. Mirrors lib/chat-typing.ts's exact pattern — same reasons apply here:
4	 *
5	 * This is a presence hint, not durable state: it never touches the database, it
6	 * expires on its own after `BOT_STEP_TTL_MS`, and — exactly like
7	 * `lib/chat-typing.ts` / `lib/rate-limit.ts` — it lives in a module-level Map.
8	 * On a horizontally-scaled deployment each instance tracks independently; that
9	 * is acceptable for a best-effort indicator, and this app runs single-process.
10	 * A signal that is never refreshed simply ages out, so a crashed or hung model
11	 * request can never leave a stuck "Checking your billing…" label showing
12	 * forever — the TTL here is intentionally short (a few seconds beyond a single
13	 * tool round-trip) so a stalled request degrades to "no step" quickly rather
14	 * than lying about what's happening.
15	 *
16	 * One label per conversation: askClaudeWithTools's `onStep` hook (see
17	 * lib/anthropic.ts) fires right before each tool call, and lib/kb-llm.ts maps
18	 * the tool name to a short human-readable label and calls `setBotStep`. The
19	 * poll endpoint (app/api/chat/route.ts) reads it back with `readBotStep` so
20	 * <ChatWidget/> can show live progress instead of a static "thinking" pulse.
21	 */
22	
23	export const BOT_STEP_TTL_MS = 9000;
24	
25	type Signal = { label: string; at: number };
26	
27	const local = new Map<string, Signal>();
28	
29	// Persist across HMR / route reloads in dev so a signal isn't lost on every edit.
30	const globalForBotStep = globalThis as unknown as { __nxeonChatBotStep?: Map<string, Signal> };
31	const store: Map<string, Signal> = globalForBotStep.__nxeonChatBotStep ?? local;
32	if (process.env.NODE_ENV !== "production") globalForBotStep.__nxeonChatBotStep = store;
33	
34	/**
35	 * Is a timestamp still "live" — i.e. within `ttl` of `now`? Pure and total:
36	 * an absent/zero/future-garbage timestamp is never active. Exported for tests,
37	 * same shape as chat-typing.ts's `isTypingActive`.
38	 */
39	export function isStepActive(at: number | undefined, now: number = Date.now(), ttl: number = BOT_STEP_TTL_MS): boolean {
40	  return typeof at === "number" && at > 0 && now - at >= 0 && now - at < ttl;
41	}
42	
43	/** Record the bot's current step label for `conversationId`. */
44	export function setBotStep(conversationId: string, label: string, now: number = Date.now()): void {
45	  if (!conversationId || !label) return;
46	  store.set(conversationId, { label, at: now });
