283	            .map((spec) => resolveActionCard(convo.userId, spec.kind, spec.id, spec.label)),
284	        )
285	      ).filter((c): c is AccountActionCard => c !== null);
286	      const cards: ChatCard[] = [...planCards, ...actionCards];
287	      await db.chatMessage.create({
288	        data: {
289	          conversationId: convo.id,
290	          sender: "bot",
291	          body: parsedActions.body,
292	          cardsJson: cards.length ? JSON.stringify(cards) : null,
293	        },
294	      });
295	    }
296	    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
297	    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
298	    // admin KB dashboard shows the bot is broken instead of it failing silently.
299	    await db.kbBotLog
300	      .create({
301	        data: {
302	          visitorId: args.visitorId,
303	          conversationId: convo.id,
304	          question: args.currentBody.slice(0, 500),
305	          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
306	          matchedTitle: result.matchedTitle ?? null,
307	        },
308	      })
309	      .catch(() => {});
310	  } catch {
311	    /* assistant is non-essential — never fail the visitor's message on it */
312	  }
313	}
